guard_re = re.compile(r'\b(pskb_may_pull_reason|pskb_may_pull|skb_linearize|pskb_pull|__pskb_pull_tail|skb_headlen|skb_is_nonlinear|skb_pagelen|skb_header_pointer|pskb_trim|skb_cow_head|skb_cow)\b')
rcv_re = re.compile(r'\b(\w*rcv\w*|\w*recv\w*|\w*input\w*|\w*decode\w*|\w*decap\w*|\w*forward\w*|\w*reasm\w*|\w*process\w*|\w*parse\w*|\w*handler\w*)\s*\(', re.I)
