for dirpath, dirs, files in os.walk(os.path.join(root, "drivers", "net")):
    for f in files:
        if f.endswith(".c"):
            results.append(os.path.join(dirpath, f))

out = []
for path in results:
    try:
        lines = open(path, errors="replace").read().split("\n")
    except Exception:
        continue
    # function extents: heuristics — a line at col 0 ending with '{' after a signature
    func_starts = []
    for i, l in enumerate(lines):
        if l.startswith("{") and i > 0:
            # previous non-empty line should look like a signature
            prev = lines[i-1].strip()
            if prev and (prev.endswith(")") or prev.endswith(",") or re.match(r'^\w[\w \*\t,\(\)]*$', prev)):
                func_starts.append(i)
    extents = []
    for s in func_starts:
        depth = 0
        for j in range(s, len(lines)):
            depth += lines[j].count("{") - lines[j].count("}")
            if depth <= 0:
                extents.append((s, j, lines[i-1].strip() if False else (lines[s-1].strip() if s>0 else "")))
                break
    for (s, e, sig) in extents:
        body = lines[s:e+1]
        text = "\n".join(body)
        hits = [(s+k, l) for k, l in enumerate(body) if acc_re.search(l)]
        if not hits:
            continue
        guards = guard_re.findall(text)
        # dereference near accessor within 3 lines after
        derefs = []
        for ln, l in hits:
            window = "\n".join(body[max(0, hits.index((ln,l))*0):])  # placeholder
        # simpler: does function contain any guard?
        out.append({
            "path": os.path.relpath(path, root),
            "start": s+1, "end": e+1, "sig": sig,
            "nhits": len(hits),
            "first_hit_line": hits[0][0]+1,
            "guards": sorted(set(guards)),
            "rcvish": bool(rcv_re.search(sig)),
        })

# rank: rcv-like functions, many accessor hits, no pull guards
scored = []
for o in out:
    pull_guards = [g for g in o["guards"] if g in ("pskb_may_pull","pskb_may_pull_reason","skb_linearize","pskb_pull","__pskb_pull_tail")]
    line_guards = [g for g in o["guards"] if g in ("skb_headlen","skb_is_nonlinear","skb_pagelen","skb_header_pointer")]
    has_guard = bool(pull_guards or line_guards)
    if not has_guard and o["rcvish"]:
        scored.append((o["nhits"], o))
scored.sort(key=lambda x: -x[0])
for n, o in scored[:60]:
    print(f'{n:3d} {o["path"]}:{o["start"]}-{o["end"]} sig={o["sig"][:90]}')
print("TOTAL funs with accessor hits:", len(out), " unguarded rcvish:", len(scored))
