239	{
240		return ((dispatch >= 0x44 && dispatch <= 0x4F) ||
241			(dispatch >= 0x51 && dispatch <= 0x5F) ||
242			(dispatch >= 0xc8 && dispatch <= 0xdf) ||
243			dispatch >= 0xe8);
244	}
