286		skb = skb_share_check(skb, GFP_ATOMIC);
287		if (!skb)
288			goto out;
289		skb->dev = ldev;
290	
291		/* When receive frag1 it's likely that we manipulate the buffer.
292		 * When recevie iphc we manipulate the data buffer. So we need
293		 * to unshare the buffer.
